    input  in,
    input  [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2
);
    reg [9:0] next_state;
    wire [9:0] state_bin;
    wire [9:0] state_onehot;
    wire [9:0] state_next_onehot;
    wire [9:0] state_next_bin;
    wire out1, out2;

    // Convert the state to a binary representation.
    assign state_bin = {state[9], state[8], state[7], state[6], state[5], state[4], state[3], state[2], state[1], state[0]};

    // Convert the state to a one-hot representation.
    assign state_onehot = 10'b0000000001 << state_bin;

    // Combine the state and input to get the next state.
    always @* begin
        case ({in, state_bin})
            {1'b0, 9'b000001010}: next_state = 10'b0000000001;
            {1'b0, 9'b000001100}: next_state = 10'b0000010000;
            {1'b0, 9'b000000111}: next_state = 10'b0000000001;
            {1'b0, 9'b000000110}: next_state = 10'b0000010000;
            {1'b0, 9'b000000001}: next_state = 10'b0000000001;
